tool_calls.arguments:
{"command":"kubectl -n default patch deploy app --type=strategic -p '{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {"name":"app","startupProbe":{"httpGet":{"path":"/","port":80,"scheme":"HTTP"},"periodSeconds":2,"timeoutSeconds":1,"successThreshold":1,"failureThreshold":15}}
        ]
      }
    }
  }
}' 2>&1; echo "---"; kubectl -n default rollout status deploy/app --timeout=60s 2>&1"}

